# Cross-Domain Discovery Engine - runnable demo (JAH-ATK199S-000001)
RANK = 1
SIG = True
DOM_A, DOM_B = [('ant foraging', [('pheromone', 'signal'), ('nest', 'hub'), ('food', 'target')]), ('delivery routing', [('gps ping', 'signal'), ('depot', 'hub'), ('customer', 'target')])]  # (domain_name, [(concept, role)])
roles_a = {role: c for c, role in DOM_A[1]}
roles_b = {role: c for c, role in DOM_B[1]}
shared = sorted(set(roles_a) & set(roles_b))
print("domain A: %s | domain B: %s" % (DOM_A[0], DOM_B[0]))
print("shared structural roles:", shared)
for role in shared:
    print("  [%s] %s (%s)  <->  %s (%s)" % (role, roles_a[role], DOM_A[0], roles_b[role], DOM_B[0]))
fidelity = len(shared) / max(1, len(set(roles_a) | set(roles_b)))
print("structural fidelity: %.2f" % fidelity)
if RANK >= 2:
    print("transfer hypothesis:" , "PROPOSE" if fidelity >= 0.4 else "REJECT (below fidelity floor)")
if RANK >= 3:
    print("roles compared:", len(set(roles_a) | set(roles_b)))
if SIG:
    print("Signature lineage stamp: JAH-SIG-XDM-" + "JAH-ATK199S-000001")
print("record:", "JAH-ATK199S-000001", "OK")

